#define UI_MAINSCREEN_SLIDER_VALUE_MIN 1
#define UI_MAINSCREEN_SLIDER_VALUE_MAX 100
#define UI_MAINSCREEN_SLIDER_Y_MIN (-5)
#define UI_MAINSCREEN_SLIDER_Y_MAX (-147)

/**
 * Return value clamped to the main-screen display range 1 through 100.
 *
 * Input: value is an arbitrary signed display scalar, not a physical CAN frame. Returns a
 * value in [1,100] with no side effects; even zero/negative measurements draw at the
 * minimum position.
 */
static int32_t ui_clamp_slider_value(int32_t value) {
  if (value < UI_MAINSCREEN_SLIDER_VALUE_MIN) {
    return UI_MAINSCREEN_SLIDER_VALUE_MIN;
  }

  if (value > UI_MAINSCREEN_SLIDER_VALUE_MAX) {
    return UI_MAINSCREEN_SLIDER_VALUE_MAX;
  }

  return value;
}

/**
 * Map the clamped 1-through-100 display value linearly to the knob Y range -5 through -147
 * using integer arithmetic; return the coordinate.
 *
 * Input: value is a display scalar. Returns a signed pixel offset relative to the centered
 * parent; larger values move upward. Clamping happens before multiplication/division, and
 * integer division yields discrete pixel steps without floating point.
 */
static int32_t ui_slider_value_to_y(int32_t value) {
  int32_t clamped = ui_clamp_slider_value(value);
  return UI_MAINSCREEN_SLIDER_Y_MIN +
         ((clamped - UI_MAINSCREEN_SLIDER_VALUE_MIN) *
          (UI_MAINSCREEN_SLIDER_Y_MAX - UI_MAINSCREEN_SLIDER_Y_MIN)) /
             (UI_MAINSCREEN_SLIDER_VALUE_MAX - UI_MAINSCREEN_SLIDER_VALUE_MIN);
}

/**
 * Return green for a clamped value through 40, orange through 65 and red above 65 for
 * temperature/power indicators.
 *
 * Input: value is a display scalar, clamped to [1,100]. Returns an RGB565 LVGL color
 * without changing an object. The thresholds are presentation constants rather than a
 * verified vehicle alarm policy.
 */
static lv_color_t ui_temp_power_slider_color(int32_t value) {
  int32_t clamped = ui_clamp_slider_value(value);

  if (clamped <= 40) {
    return lv_color_hex(0x52BA00);
  }

  if (clamped <= 65) {
    return lv_color_hex(0xF4840D);
  }

  return lv_color_hex(0xF40D0D);
}

/**
 * Return red for a clamped value through 40, orange through 65 and green above 65 for the
 * battery-level indicator.
 *
 * Input: value is a display scalar, clamped to [1,100]. Returns an RGB565 color without
 * mutation. The reversed low/red to high/green palette indicates displayed charge level,
 * with no vehicle fault decoding.
 */
static lv_color_t ui_batt_level_slider_color(int32_t value) {
  int32_t clamped = ui_clamp_slider_value(value);

  if (clamped <= 40) {
    return lv_color_hex(0xF40D0D);
  }

  if (clamped <= 65) {
    return lv_color_hex(0xF4840D);
  }

  return lv_color_hex(0x52BA00);
}

/**
 * Recolor the existing fill image with color at full opacity and leave knob recoloring
 * transparent; ignore each null image independently.
 *
 * Inputs: fill and knob are image handles or NULL, color is already an LVGL color. Returns
 * nothing; fill recoloring is fully opaque while knob source pixels retain their original
 * colors. The two null guards are independent.
 */
static void ui_set_slider_image_color(lv_obj_t *fill, lv_obj_t *knob, lv_color_t color) {
  if (fill != NULL) {
    lv_obj_set_style_img_recolor(fill, color, LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_img_recolor_opa(fill, LV_OPA_COVER, LV_PART_MAIN | LV_STATE_DEFAULT);
  }

  if (knob != NULL) {
    lv_obj_set_style_img_recolor_opa(knob, LV_OPA_TRANSP, LV_PART_MAIN | LV_STATE_DEFAULT);
  }
}

/**
 * If knob exists, move it to the coordinate mapped from value and apply color to the
 * indicator images; a null knob skips the whole update.
 *
 * Inputs: value is the normalized display scalar, color is the preselected LVGL color, and
 * fill/knob are image handles. Returns nothing; a missing knob prevents both movement and
 * recoloring, while a missing fill only skips the fill write.
 */
static void ui_set_slider_state(lv_obj_t *fill, lv_obj_t *knob, int32_t value, lv_color_t color) {
  if (knob == NULL) {
    return;
  }

  lv_obj_set_y(knob, ui_slider_value_to_y(value));
  ui_set_slider_image_color(fill, knob, color);
}

