/**
 * At most once per 40 LVGL milliseconds, advance persistent synthetic speed/slider values
 * within 1 through 100 and apply them to the main screen; no CAN data is read.
 *
 * Inputs: none; reads lv_tick_get milliseconds and static demo values/directions. Returns
 * nothing; one update is made per eligible call rather than catching up missed intervals.
 * Unsigned subtraction tolerates tick rollover; static demo state persists between calls
 * and screen recreation.
 */
void ui_step_main_screen_slider_demo(void) {
  static uint32_t last_update_ms = 0;
  static int32_t speed_value = 120;
  static int32_t speed_direction = 1;
  static int32_t batt_temp_value = 80;
  static int32_t batt_temp_direction = -1;
  static int32_t power_value = 50;
  static int32_t power_direction = 1;
  static int32_t batt_level_value = 90;
  static int32_t batt_level_direction = -1;
  uint32_t now = lv_tick_get();

  if ((now - last_update_ms) < 40U) {
    return;
  }

  last_update_ms = now;

  ui_step_demo_slider_value(&speed_value, &speed_direction, 1);
  ui_step_demo_slider_value(&batt_temp_value, &batt_temp_direction, 1);
  ui_step_demo_slider_value(&power_value, &power_direction, 2);
  ui_step_demo_slider_value(&batt_level_value, &batt_level_direction, 1);

  ui_set_speed_demo_value(speed_value);
  ui_set_batt_temp_slider_value(batt_temp_value);
  ui_set_power_consumption_slider_value(power_value);
  ui_set_batt_level_slider_value(batt_level_value);
}

