/**
 * Delete the main-screen tree if it exists and clear every associated global object
 * pointer.
 *
 * Inputs: none. Returns nothing; parent deletion precedes nulling all child handles
 * because LVGL recursively owns the tree. It is safe when the top-level handle is already
 * null; static demo counters are not reset.
 */
void ui_MainScreen_screen_destroy(void) {
  if (ui_MainScreen)
    lv_obj_del(ui_MainScreen);

  // NULL screen variables
  ui_MainScreen = NULL;
  ui_panelIMD = NULL;
  ui_panelFault = NULL;
  ui_panelRTD = NULL;
  ui_panelTSAL = NULL;
  ui_panelBSPD = NULL;
  ui_panelSDC = NULL;
  ui_panleReadyToDrive = NULL;
  ui_panelDriveMode = NULL;
  ui_labelSpeed = NULL;
  ui_labelIMD = NULL;
  ui_labelBatteryTemperature = NULL;
  ui_labelPowerConsumption = NULL;
  ui_labelBatteryLevel = NULL;
  ui_labelFault = NULL;
  ui_labelRTD = NULL;
  ui_labelTSAL = NULL;
  ui_labelBSPD = NULL;
  ui_labelSDC = NULL;
  ui_labelReadyToDrive = NULL;
  ui_labelDriveMode = NULL;
  ui_containerBattTemp = NULL;
  ui_imgBattTempFill = NULL;
  ui_imgBattTempKnob = NULL;
  ui_imgBattTempIco = NULL;
  ui_containerPowerConsumption = NULL;
  ui_imgPowerConsumptionFill = NULL;
  ui_imgPowerConsumptionKnob = NULL;
  ui_imgPowerConsumptionIco = NULL;
  ui_containerBattLevel = NULL;
  ui_imgBattLevelFill = NULL;
  ui_imgBattLevelKnob = NULL;
  ui_imgBattLevelIco = NULL;
}
